    const loop = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: black }));
    scene.add(loop);
  }
  return mesh;
}

function addDot(x, y, z = 0.05, r = 0.045, color = edgeBlue) {
