function pathPoint(path, t) {
  const segs = [];
  let total = 0;
  for (let i = 0; i < path.length - 1; i++) {
    const len = path[i].distanceTo(path[i + 1]);
    segs.push(len);
    total += len;
  }
  let drem = THREE.MathUtils.clamp(t, 0, 1) * total;
  for (let i = 0; i < segs.length; i++) {
    if (drem <= segs[i]) return path[i].clone().lerp(path[i + 1], drem / segs[i]);
    drem -= segs[i];
  }
  return path[path.length - 1].clone();
}

let animStart = 0;
let animating = false;
function startForwardAnimation() {
  animStart = performance.now();
  animating = true;
  pulseMain.visible = true;
  pulseSkip.visible = true;
  plusRing.material.color.setHex(0xdde6e8);
}
document.getElementById('resBlockForwardPass').addEventListener('click', startForwardAnimation);

function pulseLoop() {
  requestAnimationFrame(pulseLoop);
  if (!animating) return;
  const t = (performance.now() - animStart) / 3600;
  const clamped = Math.min(t, 1);
  pulseMain.position.copy(pathPoint(mainPath, clamped));
  pulseSkip.position.copy(pathPoint(skipPath, clamped));
  if (clamped > 0.78 && clamped < 0.94) {
    const glow = Math.floor(180 + 70 * Math.sin(performance.now() * 0.025));
    plusRing.material.color.setRGB(1, glow / 255, 0.05);
  } else if (clamped >= 0.94) {
    plusRing.material.color.setHex(0xffd34a);
  }
  if (t >= 1.15) {
    animating = false;
    setTimeout(() => {
      pulseMain.visible = false;
      pulseSkip.visible = false;
      plusRing.material.color.setHex(0xdde6e8);
    }, 350);
  }
}
