// forward-pass pulses → small SphereGeometry pulses moving along main and skip paths

const blue = 0xa9c4d1;
const edgeBlue = 0x2f5667;
const orange = 0xc17445;
const maxpoolBrown = 0x884526;
const bnOrange = 0xd18459;
const reluTeal = 0x90cfc7;
const convGray = 0xd7dedf;
const insetFill = 0xc9d1d3;
const teal = 0x8ed2c9;
const black = 0x111111;

function mat(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.opacity !== undefined,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? true
  });
}

function makeBox(w, h, dep, color, edgeColor = edgeBlue, pos = [0, 0, 0], name = '') {
  const group = new THREE.Group();
  group.name = name;
  const geom = new THREE.BoxGeometry(w, h, dep);
  const mesh = new THREE.Mesh(geom, mat(color));
  mesh.userData.baseColor = color;
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    new THREE.LineBasicMaterial({ color: edgeColor })
  );
  group.add(mesh, edges);
  group.position.set(pos[0], pos[1], pos[2]);
  scene.add(group);
  return group;
}

function makeLine(points, color = black, dashed = false) {
  const geom = new THREE.BufferGeometry().setFromPoints(points.map(p => new THREE.Vector3(p[0], p[1], p[2] ?? 0)));
  const material = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.12, gapSize: 0.08 })
    : new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geom, material);
  if (dashed) line.computeLineDistances();
  scene.add(line);
  return line;
}

function arrowHeadAt(pos, dir, color = black, scale = 0.06) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(scale, scale * 2.25, 18), mat(color));
  cone.position.set(pos[0], pos[1], pos[2] ?? 0);
  const v = new THREE.Vector3(dir[0], dir[1], dir[2] ?? 0).normalize();
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), v);
  scene.add(cone);
  return cone;
}

function makeArrow(a, b, color = black, scale = 0.055) {
  makeLine([a, b], color);
  arrowHeadAt(b, [b[0] - a[0], b[1] - a[1], (b[2] ?? 0) - (a[2] ?? 0)], color, scale);
}

function makeDoubleArrow(a, b, color = black, scale = 0.052) {
  makeLine([a, b], color);
  const dvec = [b[0] - a[0], b[1] - a[1], (b[2] ?? 0) - (a[2] ?? 0)];
  arrowHeadAt(b, dvec, color, scale);
  arrowHeadAt(a, [-dvec[0], -dvec[1], -dvec[2]], color, scale);
}

function makeStageBracket(x0, x1, y, z = 0.54) {
  makeLine([[x0, y - 0.16, z], [x0 + 0.30, y, z], [x1 - 0.30, y, z], [x1, y - 0.16, z]], black);
  arrowHeadAt([x0, y - 0.16, z], [-1, -0.45, 0], black, 0.048);
  arrowHeadAt([x1, y - 0.16, z], [1, -0.45, 0], black, 0.048);
}

function roundedShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function makeRoundedRect(w, h, r, color, pos, outline = true) {
  const shape = roundedShape(w, h, r);
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), mat(color, { side: THREE.DoubleSide }));
  mesh.position.set(pos[0], pos[1], pos[2] ?? 0);
  scene.add(mesh);
  if (outline) {
    const pts = shape.getPoints(10).map(p => new THREE.Vector3(p.x + pos[0], p.y + pos[1], pos[2] ?? 0.012));
    scene.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: black })));
  }
  return mesh;
}

function addDot(x, y, z = 0.08, r = 0.035, color = edgeBlue) {
  const dot = new THREE.Mesh(new THREE.SphereGeometry(r, 16, 8), mat(color));
  dot.position.set(x, y, z);
  scene.add(dot);
  return dot;
}

function setGroupTint(group, selected) {
  group.traverse(o => {
    if (o.isMesh && o.material && o.userData.baseColor) {
      o.material.color.setHex(selected ? 0x78b9d8 : o.userData.baseColor);
    }
  });
}

const rotatedLabels = [];
