function pathPoint(path, t) {
  const segs = [];
  let total = 0;
  for (let i = 0; i < path.length - 1; i++) {
    const len = path[i].distanceTo(path[i + 1]);
    segs.push(len);
    total += len;
  }
  let drem = THREE.MathUtils.clamp(t, 0, 1) * total;
  for (let i = 0; i < segs.length; i++) {
    if (drem <= segs[i]) return path[i].clone().lerp(path[i + 1], drem / segs[i]);
    drem -= segs[i];
  }
  return path[path.length - 1].clone();
}

